entradas.ejemplo:
const users = [{ id: 1, n: "Ana" }, { id: 2, n: "Luis" }];
users.find((u) => u.id === 2); // { id: 2, n: "Luis" }
users.find((u) => u.id === 9); // undefined
users.find((u) => u.id === 9)?.n; // undefined

const a = [5, 12, 8];
a.findIndex((n) => n > 10); // 1
a.findIndex((n) => n > 50); // -1

const a = [1, 2, 3];
a.map((n) => n * 2); // [2, 4, 6]
a.map((n) => ({ valor: n }))[0]; // { valor: 1 }
a.map((n) => { n * 2; }); // [undefined, undefined, undefined]
a; // [1, 2, 3]

const a = ["x", "y"];
a.forEach((letra, i) => console.log(i, letra));
// 0 x
// 1 y
a.forEach((l) => l); // undefined

const a = [1, 2, 3, 4];
a.reduce((acc, n) => acc + n, 0); // 10
["a", "b", "a"].reduce((c, x) => ({ ...c, [x]: (c[x] ?? 0) + 1 }), {}); // { a: 2, b: 1 }
[].reduce((acc, n) => acc + n, 0); // 0
[].reduce((acc, n) => acc + n); // TypeError

new Array(3).fill(0); // [0, 0, 0]
const m = new Array(2).fill([]);
m[0].push(1);
m; // [[1], [1]] (comparten el mismo arreglo)
Array.from({ length: 2 }, () => []); // [[], []]

const a = [1, 2];
[...a, 3]; // [1, 2, 3]
Math.max(...a); // 2
const m = [[1]];
const c = [...m]; c[0].push(9);
m; // [[1, 9]] (la copia es superficial)
